 70→function HealthBanner({ health, loading, onVerify }: {
 71→  health: ResendHealth | null;
 72→  loading: boolean;
 73→  onVerify: () => void;
 74→}) {
 75→  if (loading) {
 76→    return (
 77→      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
 78→        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
