106→              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
107→            </span>
108→          </div>
109→          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
110→            <RefreshCw className="h-3 w-3" /> Recheck
111→          </Button>
112→        </div>
113→        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
114→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
115→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
116→        </div>
117→      </div>
118→    );
119→  }
120→
121→  return (
122→    <div className="space-y-2">
123→      {issues.map((issue, i) => (
124→        <div
125→          key={i}
126→          className={`rounded-lg border p-3 flex items-start gap-2 ${
127→            issue.severity === "error"
128→              ? "border-destructive/50 bg-destructive/10 text-destructive"
129→              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
130→          }`}
131→        >
132→          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
133→          <p className="text-xs">{issue.text}</p>
134→        </div>
135→      ))}
136→      <div className="flex justify-end">
137→        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
138→          <RefreshCw className="h-3 w-3" /> Recheck
139→        </Button>
140→      </div>
141→    </div>
142→  );
143→}
