852→function NotificationCard({
853→  icon: Icon, label, description, checked, onToggle, disabled,
854→  template, onSaveTemplate, savingTemplate
855→}: {
856→  icon: React.ElementType; label: string; description: string;
857→  checked: boolean; onToggle: (v: boolean) => void; disabled: boolean;
858→  template?: { id: string; template_key: string; subject: string; body_html: string; description: string | null };
859→  onSaveTemplate: (subject: string, body_html: string) => void;
860→  savingTemplate: boolean;
